export function suggest(prefix, limit = 4) {
  const p = prefix.toLowerCase();
  if (!p) return [];
  const out = [];
  for (const w of WORDS) {
    if (w.length > p.length && w.startsWith(p)) {
      out.push(w);
      if (out.length === limit) break;
    }
  }
  return out;
}
